 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]

    # Repeated isolated points are stamp centers; the non-marker object is
    # the source stamp, whose bounding box (including background cells) matters.
    colors = [v for v in counts if v != bg]
    def isolated_count(color):
        total = 0
        for r in range(h):
            for c in range(w):
                if grid[r][c] != color:
                    continue
                if all(not (0 <= r + dr < h and 0 <= c + dc < w and grid[r + dr][c + dc] == color)
                       for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1))):
                    total += 1
        return total
    marker = max(colors, key=lambda v: (isolated_count(v), counts[v]))
    source = [(r, c) for r in range(h) for c in range(w)
              if grid[r][c] != bg and grid[r][c] != marker]
    if not source:
        return [row[:] for row in grid]
    r0, r1 = min(r for r, c in source), max(r for r, c in source)
    c0, c1 = min(c for r, c in source), max(c for r, c in source)
    pattern = [row[c0:c1 + 1] for row in grid[r0:r1 + 1]]
    cr, cc = (r1 - r0) // 2, (c1 - c0) // 2
    anchors = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]
    out = [row[:] for row in grid]
    for ar, ac in anchors:
        for i, row in enumerate(pattern):
            for j, value in enumerate(row):
                y, x = ar + i - cr, ac + j - cc
                if 0 <= y < h and 0 <= x < w:
                    out[y][x] = value
    return out

if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
